export const reconciliationDispositions = ["retain", "merge", "redirect", "retire"] as const;
export type ReconciliationDisposition = (typeof reconciliationDispositions)[number];

type Item = Readonly<{
  id: string;
  sourcePath: string;
  disposition: ReconciliationDisposition;
  canonicalPath: string | null;
}>;

const freeze = <T extends object>(rows: readonly T[]): readonly Readonly<T>[] =>
  Object.freeze(rows.map((row) => Object.freeze({...row})));

const items = (prefix: string, rows: readonly string[]): readonly Item[] =>
  freeze(rows.map((row, index) => {
    const [sourcePath, disposition, canonicalPath] = row.split("|");
    return {
      id: prefix + String(index + 1).padStart(2, "0"),
      sourcePath: sourcePath === "/" ? "/" : "/" + sourcePath,
      disposition: disposition as ReconciliationDisposition,
      canonicalPath: canonicalPath || null,
    };
  }));

